head.script:
scwin.screenId = "jldfil70702";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_formGubun", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'VIEW'); } }, { id: "tr_23", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'VIEW'); } }, { id: "tr_27", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'VIEW'); } }, { id: "tr_31", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'VIEW'); } }, { id: "tr_35", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'VIEW'); } }, { id: "tr_39", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'VIEW'); } }, { id: "tr_43", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'VIEW'); } }, { id: "tr_50", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'VIEW'); } }, { id: "tr_54", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'VIEW'); } }, { id: "if_formGubun_2", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'NEW'); } }, { id: "tr_59", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'NEW'); } }, { id: "tr_63", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'NEW'); } }, { id: "tr_67", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'NEW'); } }, { id: "tr_71", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'NEW'); } }, { id: "tr_75", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'NEW'); } }, { id: "tr_82", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'NEW'); } }, { id: "tr_86", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'NEW'); } }, { id: "btn_Register", fn: function(){ return ((dma_readDataVO.get("formGubun") ?? (() => { throw new Error("unresolved:" + "readDataVO.formGubun"); })()) === 'NEW'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// [A] 초기 목록 미해결 — jldfil70702: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil70702.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Search_onclick = function(e){
    const ev = e;
    const event = ev;
    const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
    /* sdd-asis-lifecycle:begin btn_Search_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.search()
    /* sdd-asis-lifecycle:end */
};

/**
 * @event
 * @name scwin.__ev_2_btn_Search_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.__ev_2_btn_Search_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin __ev_2_btn_Search_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.search()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil70702.__ev_2_btn_Search_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_Register_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Register_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Register_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.register()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil70702.btn_Register_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_Search_2_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Search_2_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Search_2_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.search()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil70702.btn_Search_2_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.register = async function () {
    /* sdd-asis-lifecycle:begin fn_Register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!$c.lc.fn_isProcess('I')) {
        return;
    }
    if (!await scwin.validate()) {
        return;
    }
    form = (document.etnSrtyForm || { elements: [] });
    form.method.value = 'insertEtnSrty';
    form.submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    form = (document.etnSrtyForm || { elements: [] });
    form.method.value = 'searchEtnSrty';
    form.submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.validate = async function () {
    /* sdd-asis-lifecycle:begin fn_validate — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const elem = $c.util.getComponent('etnSrtyForm').elements;
    for (let i = 0; i < elem.length; i++) {
        if (elem[i].type !== 'hidden') {
            if (elem[i].name.indexOf('srtyKindContn') >= 0) {
                continue;
            }
            if (elem[i].value === '') {
                await $c.win.alert('[' + elem[i].id + "] 항목값을 입력해주세요.");
                console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return false;
            }
            if (elem[i].name === 'srtyNm') {
                if (!fn_checkLength(elem[i], 100)) {
                    console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
                    return false;
                }
            }
            if (elem[i].name === 'srtyAbbrv') {
                if (!fn_checkLength(elem[i], 50)) {
                    console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
                    return false;
                }
            }
            if (elem[i].name === 'srtyEngNm') {
                if (!fn_checkLength(elem[i], 100)) {
                    console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
                    return false;
                }
            }
            if (elem[i].name === 'srtyEngAbbrv') {
                if (!fn_checkLength(elem[i], 50)) {
                    console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
                    return false;
                }
            }
            if (elem[i].name === 'cntrCd') {
                if (!fn_checkLength(elem[i], 3)) {
                    console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
                    return false;
                }
            }
            if (elem[i].name === 'addr') {
                if (!fn_checkLength(elem[i], 200)) {
                    console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
                    return false;
                }
            }
            if (elem[i].name === 'srtyKindContn') {
                if (!fn_checkLength(elem[i], 40)) {
                    console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
                    return false;
                }
            }
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};
